#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<int> a1, a2;
    int n1 = n / 2;

    function<void(int, int)> sums1 = [&](int i, int sum) {
        if (i == n1) {
            a1.push_back(sum % m);
        } else {
            sums1(i + 1, sum + a[i]);
            sums1(i + 1, sum);
        }
    };

    function<void(int, int)> sums2 = [&](int i, int sum) {
        if (i == n) {
            a2.push_back(sum % m);
        } else {
            sums2(i + 1, sum + a[i]);
            sums2(i + 1, sum);
        }
    };

    sums1(0, 0);
    sums2(n1, 0);

    int ans = 0;
    int end = (int)a2.size() - 1;

    // Remove duplicates and sort a1
    sort(a1.begin(), a1.end());
    a1.erase(unique(a1.begin(), a1.end()), a1.end());

    auto bisect_left = [](const vector<int>& v, int x) {
        return (int)std::lower_bound(v.begin(), v.end(), x) - v.begin();
    };

    auto solve = [&](int i) {
        int j = bisect_left(a1, m - i);
        if (j == 0) {
            // no valid j, skip
            return 0;
        }
        int candidate = a1[j - 1] + i;
        if (candidate > ans) {
            ans = candidate;
        }
        return ans;
    };

    vector<int> l;
    for (int val : a2) {
        l.push_back(solve(val));
    }
    cout << l.back() << "\n";

    return 0;
}
